{
  "items": [
    {
      "requirement_id": "SC-001",
      "type": "scope_context",
      "statement": "The project is a free graphical tool for manipulating PDF documents.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T002"]
    },
    {
      "requirement_id": "SC-002",
      "type": "scope_context",
      "statement": "The tool must allow users to manipulate PDF documents without altering the original input files.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T002"]
    },
    {
      "requirement_id": "SC-003",
      "type": "scope_context",
      "statement": "The tool must support both visual, manual work and command-line use for repeatable tasks.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T002"]
    },
    {
      "requirement_id": "ST-001",
      "type": "stakeholder_actor",
      "statement": "The tool is intended for users who need everyday PDF handling, including casual users working through a graphical interface and users performing automated or recurring jobs through the command line.",
      "status": "stated",
      "source_ids": ["T004", "T002", "INITIAL_REQUIREMENTS"]
    },
    {
      "requirement_id": "FR-001",
      "type": "functional_requirement",
      "statement": "The system shall support splitting PDF documents.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T004", "T008"]
    },
    {
      "requirement_id": "FR-002",
      "type": "functional_requirement",
      "statement": "The system shall support merging selected files or sections.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS"]
    },
    {
      "requirement_id": "FR-003",
      "type": "functional_requirement",
      "statement": "The system shall support extracting selected pages from PDF documents.",
      "status": "stated",
      "source_ids": ["T010"]
    },
    {
      "requirement_id": "FR-004",
      "type": "functional_requirement",
      "statement": "The system shall support rotating pages.",
      "status": "stated",
      "source_ids": ["T012"]
    },
    {
      "requirement_id": "FR-005",
      "type": "functional_requirement",
      "statement": "The system shall support reordering pages.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T008"]
    },
    {
      "requirement_id": "FR-006",
      "type": "functional_requirement",
      "statement": "The system shall support alternating pages from different documents.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T010"]
    },
    {
      "requirement_id": "FR-007",
      "type": "functional_requirement",
      "statement": "The system shall support visually composing new documents.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T008"]
    },
    {
      "requirement_id": "FR-008",
      "type": "functional_requirement",
      "statement": "The system shall allow users to save reusable work environments or setups.",
      "status": "stated",
      "source_ids": ["T010"]
    },
    {
      "requirement_id": "FR-009",
      "type": "functional_requirement",
      "statement": "The system shall provide a command-line path for recurring or automated operations.",
      "status": "stated",
      "source_ids": ["INITIAL_REQUIREMENTS", "T002", "T004", "T008"]
    }
  ]
}
